def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'D'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp_d = 0
    my_d = 0
    for m, o in history:
        if o == 'D':
            opp_d += 1
        if m == 'D':
            my_d += 1

    last_me, last_opp = history[-1]

    if n == 99:
        return 'D'

    if opp_d == 0:
        return 'D'

    if opp_d > n * 0.7:
        if n < 95 and rng.random() < 0.15:
            return 'C'
        return 'D'

    consec_d = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        consec_d += 1
        i -= 1
    if consec_d >= 3:
        if n < 95 and rng.random() < 0.25:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if my_d > opp_d + 1:
            return 'C'
        if n < 95 and rng.random() < 0.15:
            return 'C'
        return 'D'
    else:
        if last_me == 'D' and n < 95:
            return 'D'
        if n < 90 and rng.random() < 0.05:
            return 'D'
        return 'C'
